files.content:
body {
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  min-block-size: 100dvh;
}

div {
  background:
    repeating-linear-gradient(
      -45deg,
      transparent 0,
      transparent 25%,
      dodgerblue 0,
      dodgerblue 50%
    ),
    repeating-linear-gradient(
      45deg,
      transparent 0,
      transparent 25%,
      tomato 0,
      tomato 50%
    ),
    repeating-linear-gradient(transparent 0, transparent 25%, gold 0, gold 50%),
    white;
  background-size: 100px 100px;
  inline-size: 100%;
  block-size: 100dvh;
  background-blend-mode: multiply;
}
